#define _GNU_SOURCE

#include <dlfcn.h>
#include <stddef.h>
#include <string.h>
#include <unistd.h>

typedef ssize_t (*readlink_function)(const char *, char *, size_t);

/*
 * Elan probes /proc/<pid>/exe to identify a multicall application.  The audit
 * process wrapper obscures that parent path, so answer every such probe with
 * the current process executable.  This changes only tool discovery.
 */
ssize_t readlink(const char *path, char *buffer, size_t size) {
    static readlink_function real_readlink = NULL;
    if (real_readlink == NULL) {
        real_readlink = (readlink_function)dlsym(RTLD_NEXT, "readlink");
    }
    size_t length = strlen(path);
    if (length > 10 &&
        strncmp(path, "/proc/", 6) == 0 &&
        strcmp(path + length - 4, "/exe") == 0) {
        return real_readlink("/proc/self/exe", buffer, size);
    }
    return real_readlink(path, buffer, size);
}
